function VirtualBackground({ _jitsiTrack, _selectedThumbnail, _virtualSource, dispatch, t }: Props) {
    const [ options, setOptions ] = useState({});
    const localImages = jitsiLocalStorage.getItem('virtualBackgrounds');
    const [ storedImages, setStoredImages ] = useState((localImages && JSON.parse(localImages)) || []);
    const [ loading, isloading ] = useState(false);
    const [ activeDesktopVideo ] = useState(_virtualSource?.videoType === VIDEO_TYPE.DESKTOP ? _virtualSource : null);

    const deleteStoredImage = image => {
        setStoredImages(storedImages.filter(item => item !== image));
    };

    useEffect(() => {
        try {
            jitsiLocalStorage.setItem('virtualBackgrounds', JSON.stringify(storedImages));
        } catch (err) {
            err && deleteStoredImage(storedImages[0]);
        }
        if (storedImages.length === backgroundsLimit) {
            deleteStoredImage(storedImages[0]);
        }
    }, [ storedImages ]);

    const enableBlur = async (blurValue, selection) => {
        setOptions({
            backgroundType: VIRTUAL_BACKGROUND_TYPE.BLUR,
            enabled: true,
            blurValue,
            selectedThumbnail: selection
        });
    };

    const removeBackground = async () => {
        setOptions({
            enabled: false,
            selectedThumbnail: 'none'
        });
    };

    const shareDesktop = async selection => {
        const url = await createLocalTrack('desktop', '');

        if (!url) {
            dispatch(showErrorNotification({
                titleKey: 'virtualBackground.desktopShareError'
            }));
            logger.error('Could not create desktop share as a virtual background!');

            return;
        }
        setOptions({
            backgroundType: VIRTUAL_BACKGROUND_TYPE.DESKTOP_SHARE,
            enabled: true,
            selectedThumbnail: selection,
            url
        });
    };

    const setUploadedImageBackground = async image => {
        setOptions({
            backgroundType: VIRTUAL_BACKGROUND_TYPE.IMAGE,
            enabled: true,
            url: image.src,
            selectedThumbnail: image.id
        });
    };

    const setImageBackground = async image => {
        const url = await toDataURL(image.src);

        setOptions({
            backgroundType: VIRTUAL_BACKGROUND_TYPE.IMAGE,
            enabled: true,
            url,
            selectedThumbnail: image.id
        });
    };

    const uploadImage = async imageFile => {
        const reader = new FileReader();

        reader.readAsDataURL(imageFile[0]);
        reader.onload = async () => {
            const url = await resizeImage(reader.result);
            const uuId = uuid.v4();

            setStoredImages([
                ...storedImages,
                {
                    id: uuId,
                    src: url
                }
            ]);
            setOptions({
                backgroundType: VIRTUAL_BACKGROUND_TYPE.IMAGE,
                enabled: true,
                url,
                selectedThumbnail: uuId
            });
        };
        reader.onerror = () => {
            isloading(false);
            logger.error('Failed to upload virtual image!');
        };
    };

    const applyVirtualBackground = async () => {
        if (activeDesktopVideo) {
            await activeDesktopVideo.dispose();
        }
        isloading(true);
        await dispatch(toggleBackgroundEffect(options, _jitsiTrack));
        await isloading(false);
        dispatch(hideDialog());
    };

    return (
        <Dialog
            hideCancelButton = { false }
            okKey = { 'virtualBackground.apply' }
            onSubmit = { applyVirtualBackground }
            submitDisabled = { !options || loading }
            titleKey = { 'virtualBackground.title' } >
            <VirtualBackgroundPreview options = { options } />
            {loading ? (
                <div className = 'virtual-background-loading'>
                    <Spinner
                        isCompleting = { false }
                        size = 'medium' />
                </div>
            ) : (
                <div>
                    <label
                        className = 'file-upload-label'
                        htmlFor = 'file-upload'>
                        <Icon
                            className = { 'add-background' }
                            size = { 20 }
                            src = { IconPlusCircle } />
                        {t('virtualBackground.addBackground')}
                    </label>
                    <input
                        accept = 'image/*'
                        className = 'file-upload-btn'
                        id = 'file-upload'
                        onChange = { e => uploadImage(e.target.files) }
                        type = 'file' />
                    <div className = 'virtual-background-dialog'>
                        <div
                            className = { _selectedThumbnail === 'none' ? 'none-selected' : 'virtual-background-none' }
                            onClick = { removeBackground }>
                            {t('virtualBackground.none')}
                        </div>
                        <div
                            className = { _selectedThumbnail === 'slight-blur'
                                ? 'slight-blur-selected' : 'slight-blur' }
                            onClick = { () => enableBlur(8, 'slight-blur') }>
                            {t('virtualBackground.slightBlur')}
                        </div>
                        <div
                            className = { _selectedThumbnail === 'blur' ? 'blur-selected' : 'blur' }
                            onClick = { () => enableBlur(25, 'blur') }>
                            {t('virtualBackground.blur')}
                        </div>
                        <div
                            className = { _selectedThumbnail === 'desktop-share'
                                ? 'desktop-share-selected'
                                : 'desktop-share' }
                            onClick = { () => shareDesktop('desktop-share') }>
                            <Icon
                                className = 'share-desktop-icon'
                                size = { 30 }
                                src = { IconShareDesktop } />
                        </div>
                        {images.map((image, index) => (
                            <img
                                className = {
                                    options.selectedThumbnail === image.id || _selectedThumbnail === image.id
                                        ? 'thumbnail-selected'
                                        : 'thumbnail'
                                }
                                key = { index }
                                onClick = { () => setImageBackground(image) }
                                onError = { event => event.target.style.display = 'none' }
                                src = { image.src } />
                        ))}
                        {storedImages.map((image, index) => (
                            <div
                                className = { 'thumbnail-container' }
                                key = { index }>
                                <img
                                    className = { _selectedThumbnail === image.id ? 'thumbnail-selected' : 'thumbnail' }
                                    onClick = { () => setUploadedImageBackground(image) }
                                    onError = { event => event.target.style.display = 'none' }
                                    src = { image.src } />
                                <Icon
                                    className = { 'delete-image-icon' }
                                    onClick = { () => deleteStoredImage(image) }
                                    size = { 15 }
                                    src = { IconCloseSmall } />
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </Dialog>
    );
}

function nestedObjectAssign(target, ...sources){
    if (!sources.length)
        return target;

    const source = sources.shift();

    if (isObject(target) && isObject(source)){
        for (const key in source){
            if (isObject(source[key]) && !isPrototypePolluted(key)){
                if (!target[key]) {
                    Object.assign(target, {[key]: {}});
                }

                nestedObjectAssign(target[key], source[key]);
            } else if (isArray(source[key])) {
                if (!target[key]) {
                    Object.assign(target, {[key]: []});
                }

                target[key] = target[key].concat(source[key]);
            } else {
                Object.assign(target, {[key]: source[key]});
            }
        }
    }

    return nestedObjectAssign(target, ...sources);
}

