              super(...arguments);
              this.channel = channel;
              this.chatService = chatService;
            }

            get name() {
              return dasherize(this.channel.title);
            }

            get route() {
              return "chat.channel";
            }

            get models() {
              return [this.channel.id, slugifyChannel(this.channel.title)];
            }

            get title() {
              return this.channel.title;
            }

