async function createMdxNodeExtraBabel({ id, node, content, options }) {
  let code
  try {
    code = await mdx(content, { filepath: node.absolutePath, ...options })
  } catch (e) {
    e.message += `${node.absolutePath}: ${e.message}`
    throw e
  }

  const { frontmatter, ...nodeExports } = extractExports(
    code,
    node.absolutePath
  )

  const mdxNode = {
    id,
    children: [],
    parent: node.id,
    internal: {
      content: content,
      type: `Mdx`,
    },
  }

  mdxNode.frontmatter = {
    title: ``,
    ...frontmatter,
  }

  mdxNode.excerpt = frontmatter.excerpt
  mdxNode.exports = nodeExports
  mdxNode.rawBody = content

  if (node.internal.type === `File`) {
    mdxNode.fileAbsolutePath = node.absolutePath
  }

  mdxNode.internal.contentDigest = createContentDigest(mdxNode)

  return mdxNode
}

function merge(target, obj) {
  for (var key in obj) {
    if (key === '__proto__' || !hasOwn(obj, key)) {
      continue;
    }

    var oldVal = obj[key];
    var newVal = target[key];

    if (utils.isObject(newVal) && utils.isObject(oldVal)) {
      target[key] = merge(newVal, oldVal);
    } else if (Array.isArray(newVal)) {
      target[key] = utils.union([], newVal, oldVal);
    } else {
      target[key] = utils.clone(oldVal);
    }
  }
  return target;
}

